# generated by Gemini 3 Pro
import numpy as np
import scipy.io.wavfile as wav
import os


def save_audio(
    signal: np.ndarray,
    fs: int,
    filename: str,
    normalize: bool = True,
    gain: float = 0.5,
):
    """
    信号を WAV ファイルとして保存する汎用関数。
    モノラル(1 次元)とステレオ(2 次元)の両方に対応する。

    Args:
        signal (np.ndarray): 音声信号。Shapeは (N,) または (N, 2)
        fs (int): サンプリング周波数
        filename (str): 保存先のパス
        normalize (bool): Trueならピークを gain に合わせる。
                          ステレオの場合は左右の振幅比(定位)を保持して正規化する
        gain (float): 目標ピーク振幅 (0.0 〜 1.0)。
    """

    audio_data = signal.copy()

    # モノラル/ステレオの判定 (ログ出力用)
    channels = 1
    if audio_data.ndim == 2:
        channels = audio_data.shape[1]

    mode_str = "Stereo" if channels == 2 else "Mono"

    # 1. 直流オフセットの除去
    audio_data = audio_data - np.mean(audio_data, axis=0)

    # 2. 振幅の正規化
    if normalize:
        # ステレオの場合、全チャネル共通の最大値で除算し、左右の振幅比(パンニング)を保持する
        max_val = np.max(np.abs(audio_data))
        if max_val > 0:
            audio_data = (audio_data / max_val) * gain
    else:
        audio_data = audio_data * gain

    # 3. float32 から int16 へ量子化 (範囲外の値は飽和させる)
    # -1.0〜1.0 に制限する
    audio_data = np.clip(audio_data, -1.0, 1.0)
    audio_int16 = (audio_data * 32767).astype(np.int16)

    os.makedirs(
        os.path.dirname(filename) if os.path.dirname(filename) else ".", exist_ok=True
    )
    wav.write(filename, int(fs), audio_int16)
    print(f"Saved [{mode_str}] audio to: {filename} (Gain: {gain})")
